 % compute trend only on g
ETL_tr.BaB_Ah=[];
ETL_tr.BaR_Ah=[];
ETL_tr.BsB_Sh=[];
ETL_tr.BsR_Sh=[];

ETL_tr.BbsB_Sh=[];
ETL_tr.BbsR_Sh=[];

ETL_tr.BbsFb=[];
ETL_tr.BbsFr=[];

 ETL_tr.expA_br=[];
 ETL_tr.expA_gr=[];

ETL_tr.expS_br=[];
ETL_tr.expS_gr=[];
ETL_tr.expS_bg=[];
%%
[ETL_result_MK,ETL_result_LMSlog,ETL_result_LMSlin]=all_trend_STN(ETL_tr,ETL_st); %[output:40b58adc] %[output:3133bde4] %[output:5f93f6c8]

writetable(ETL_result_MK,'ETL_res_MK_present_10y.txt'); %, 'delimiter',',' )
writetable(ETL_result_LMSlog,'ETL_res_LMSlog.txt'); 
writetable(ETL_result_LMSlin,'ETL_res_LMSlin.txt'); 
plot_10y_in_two(ETL_result_MK, ETL_st,'y');
